parameters.jsCode:
// Aqui se juntan todas las ramas y salen los campos que espera el resto del
// workflow. Trece nodos leen $('Extraer mensaje'), asi que este contrato
// --from, message_text, contact_name, client_id-- no se toca.
const base = $('Leer webhook').first().json;
const entrada = $input.first().json || {};
const client_id = $('Buscar cliente Whatsapp').first().json.client_id;

// De donde viene el texto depende de por donde se haya pasado. Se mira la forma
// del item, no de que nodo viene: referenciar un nodo que no se ha ejecutado
// --$('Transcribir audio') cuando llego un PDF-- da error en n8n.
//   Whisper          -> { text }
//   vision           -> { choices: [...] }
//   subida a Storage -> { Key }
//   demasiado grande -> { url, file_size } (la ficha del medio, sin descargar)
//   texto normal     -> { client_id, config } (la ficha del cliente)
const transcripcion = typeof entrada.text === 'string' ? entrada.text.trim() : '';
const descripcion = String(entrada.choices?.[0]?.message?.content || '').trim();
const demasiado_grande = Boolean(entrada.url && entrada.file_size);

// La ruta se calcula, no se arrastra: con el id del medio y el del cliente basta,
// y ambos estan disponibles vengamos por donde vengamos.
const guardado = Boolean(base.media_id) && !demasiado_grande;
const media_path = guardado ? client_id + '/' + base.media_id + '.' + base.ext : null;

const partes = [];
if (base.texto) partes.push(base.texto);
if (base.pie) partes.push(base.pie);
if (transcripcion) partes.push(transcripcion);
if (descripcion) partes.push('En la foto se ve: ' + descripcion);

// Esto es lo que se guarda en la bandeja y lo que lee el modelo. Cuando no hay
// nada legible se deja una marca entre corchetes en vez de una cadena vacia:
// en la bandeja, un mensaje en blanco parece un fallo del panel.
const message_text =
  partes.reduce((acc, p) => (acc ? acc + (/[.!?…]$/.test(acc) ? ' ' : '. ') + p : p), '') ||
  (base.etiqueta ? '[' + base.etiqueta + ']' : '');

return [{
  json: {
    phone_number_id: base.phone_number_id,
    from: base.from,
    contact_name: base.contact_name,
    // `Buscar prompt del cliente` lo lee de su item de entrada, asi que tiene
    // que seguir viajando por aqui.
    client_id,
    message_text,
    // El archivo, para que lo abra quien atienda desde la bandeja.
    media_path,
    media_type: guardado ? base.mime : null,
    media_name: guardado ? base.nombre_archivo : null,
    // Para que `Preparar contexto` pueda avisar al modelo de que lo que llego
    // no era texto, y de si se ha podido leer o no.
    adjunto: base.tipo === 'text' ? null : {
      etiqueta: demasiado_grande ? base.etiqueta + ', demasiado grande para guardarlo' : base.etiqueta,
      leido: Boolean(transcripcion || descripcion),
    },
  }
}];

