parameters.jsCode:
// Historial: Supabase nos lo devuelve del más nuevo al más viejo,
// así que lo invertimos para dárselo a la IA en orden cronológico.
const previos = $input.all()
  .map((i) => i.json)
  .filter((m) => m.role && m.content)
  .reverse()
  .map((m) => ({ role: m.role, content: m.content }));

// Ojo: este nodo recibe varios items (uno por mensaje del historial), así que
// hay que usar .first() y no .item, que aquí no existe.
const cfg = $('Buscar prompt del cliente').first().json;

// === Presentarse como asistente ===
// Quien escribe tiene que saber que le contesta un asistente automatico y no
// una persona (lo promete el contrato y lo exige el art. 50 del Reglamento
// europeo de IA). Toca presentarse cuando:
//   - es una conversacion nueva: no hay ningun mensaje nuestro;
//   - lo ultimo que se le escribio lo escribio una persona desde el panel: si
//     ahora contesta el bot sin decir nada, creeria que sigue hablando con ella;
//   - el bot no le escribe desde hace mas de 30 dias.
// El historial llega del mas nuevo al mas viejo, asi que el primero que
// encontramos de los nuestros es el ultimo que se le mando.
const TREINTA_DIAS = 30 * 24 * 60 * 60 * 1000;
const ultimoNuestro = $input.all()
  .map((i) => i.json)
  .find((m) => m.sender === 'bot' || m.sender === 'human');
const presentarse =
  !ultimoNuestro ||
  ultimoNuestro.sender === 'human' ||
  new Date() - new Date(ultimoNuestro.created_at) > TREINTA_DIAS;

const busqueda = $('Preparar búsqueda').first().json || {};
const fragmentos = ($('Recoger conocimiento').first().json || {}).fragmentos || [];
const productos = ($('Recoger productos').first().json || {}).productos || [];

// === Conocimiento del negocio (RAG) ===
// Lo recuperado para ESTA pregunta, no la base entera. Va como bloque propio y
// con reglas explícitas: sin ellas el modelo rellena los huecos por su cuenta,
// que es justo lo que no se quiere en una tienda de verdad.
const conocimiento = [];

if (fragmentos.length) {
  conocimiento.push('=== INFORMACION DEL NEGOCIO ===');
  // El texto del fragmento ya viene con su título delante desde el indexado.
  conocimiento.push(
    fragmentos
      .map((f) => f.content + (f.source_url ? '\nMas informacion: ' + f.source_url : ''))
      .join('\n\n')
  );
}

// El catálogo guarda el precio como número, y al pegarlo tal cual salía
// «12.74 EUR» en el chat: punto decimal y el código de la moneda. En España
// eso no lo escribe nadie, y en un mensaje de WhatsApp canta. Se formatea
// aquí, y no pidiéndoselo al modelo, porque un modelo que reescribe cifras
// alguna vez se equivoca de cifra.
function enEuros(valor, moneda) {
  const n = Number(valor);
  if (!isFinite(n)) return String(valor);
  const [enteros, decimales] = n.toFixed(2).split('.');
  // Punto de millar: 1234.5 -> «1.234,50».
  const conMiles = enteros.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const simbolo = !moneda || moneda === 'EUR' ? '€' : moneda;
  return conMiles + ',' + decimales + ' ' + simbolo;
}

if (productos.length) {
  conocimiento.push('=== PRODUCTOS DEL CATALOGO ===');
  conocimiento.push(
    productos
      .map((p) => {
        const precio = p.price === null || p.price === undefined ? 'consultar' : enEuros(p.price, p.currency);
        return '- ' + p.name + ': ' + precio + (p.available === false ? ' (agotado)' : '') + ' -> ' + p.url;
      })
      .join('\n')
  );
}

if (conocimiento.length) {
  conocimiento.push([
    'Reglas sobre esta informacion:',
    '- Para precios, plazos, politicas o caracteristicas del negocio, responde UNICAMENTE con lo de arriba.',
    '- Si el dato no esta ahi, dilo con naturalidad y ofrece el contacto humano. NUNCA te inventes precios, plazos ni condiciones.',
    '- Los precios de la lista de productos son los validos: no los redondees, no los estimes y no des rangos inventados.',
    '- Copia los precios EXACTAMENTE como aparecen, con su coma decimal y su simbolo del euro. No los reescribas con punto ni cambies EUR por otra cosa.',
    '- Si mencionas un producto concreto, incluye su enlace.',
  ].join('\n'));
}

// === Agenda ===
// Solo para clientes con el modulo de agenda activo. Una tienda que no reserva
// citas no debe recibir nada de esto: si le metes un calendario en el contexto,
// el modelo acaba ofreciendo horas a quien preguntaba por un capazo.
const calendario = [];

if (busqueda.tiene_agenda) {
  // Los huecos los calcula la Agenda API, no este nodo: es la misma fuente que
  // usa el agente de voz.
  const agenda = $('Consultar agenda').first().json || {};
  const libres = agenda.dias || [];
  // Lo que se puede reservar, y lo que se ha entendido de ESTE mensaje. El
  // motor deduce el servicio de la frase, asi que en cuanto alguien escribe
  // "unas mechas" los huecos de abajo ya son de 150 minutos y no de 60.
  const catalogo = agenda.catalogo || [];
  const servicioDetectado = (agenda.servicios || [])[0] || null;
  const duracion = agenda.duracion_min || 60;
  const paso = agenda.paso_min || 15;

  const aMin = (h) => { const [a, b] = h.split(':').map(Number); return a * 60 + b; };
  const dosCifras = (n) => String(n).padStart(2, '0');
  const aTexto = (m) => dosCifras(Math.floor(m / 60)) + ':' + dosCifras(m % 60);

  function rangos(horas) {
    const out = [];
    let ini = null;
    let prev = null;
    for (const h of horas) {
      const m = aMin(h);
      if (prev !== null && m === prev + paso) { prev = m; continue; }
      if (ini !== null) out.push(ini === prev ? aTexto(ini) : aTexto(ini) + '-' + aTexto(prev));
      ini = m;
      prev = m;
    }
    if (ini !== null) out.push(ini === prev ? aTexto(ini) : aTexto(ini) + '-' + aTexto(prev));
    return out.join(', ');
  }

  // La IA no sabe qué día de la semana cae cada fecha. Le damos los próximos
  // 7 días: exactamente 7, para que cada nombre de día aparezca UNA sola vez.
  const proximosDias = [];
  for (let i = 0; i < 7; i++) {
    const d = $now.plus({ days: i });
    proximosDias.push(`${d.setLocale('es').toFormat('cccc')} = ${d.toFormat('yyyy-MM-dd')}`);
  }

  // Cada servicio dura lo suyo, asi que una hora no significa nada hasta saber
  // cual es. Sin esta lista el modelo se inventa un catalogo plausible --y en
  // una peluqueria acierta de lleno, que es lo peligroso: nombres que suenan
  // bien y que el negocio no hace.
  if (catalogo.length) {
    calendario.push([
      '=== SERVICIOS QUE SE PUEDEN RESERVAR (los unicos que existen) ===',
      catalogo.map((s) => `- ${s.nombre} (${s.duracion_min} min)`).join('\n'),
      servicioDetectado
        ? `De este mensaje se ha entendido: ${servicioDetectado.nombre}. Los huecos de abajo son para eso.`
        : 'Todavia no se sabe que quiere hacerse. Los huecos de abajo son de una cita estandar y NO valen para un servicio largo: si quiere cita, preguntale primero que se va a hacer.',
      '',
    ].join('\n'));
  }

  calendario.push([
    '=== CALENDARIO REAL (esta es la unica fuente valida de fechas) ===',
    `Hoy es ${$now.setLocale('es').toFormat('cccc')} ${$now.toFormat('yyyy-MM-dd')} (Europe/Madrid).`,
    proximosDias.join('\n'),
    'Reglas de fechas:',
    '- Si el usuario nombra un dia de la semana ("el viernes"), usa EXACTAMENTE la fecha de esta lista.',
    '- Si nombra una fecha concreta ("el 31 de julio"), respetala tal cual y NO la corrijas.',
    '- Los mensajes anteriores pueden contener fechas equivocadas: ignoralas y usa solo esta lista.',
    // La lista va en AAAA-MM-DD porque de ahi sale el campo date, que es el que
    // reserva. Pero el modelo copia el formato que ve, y al cliente le llegaba
    // «el jueves 2026-09-24». Se separan las dos cosas con una regla.
    '- En el texto de reply escribe las fechas como DD-MM-AAAA ("el jueves 24-09-2026"), NUNCA como AAAA-MM-DD. El campo date sigue siempre en AAAA-MM-DD.',
    '',
    servicioDetectado
      ? `=== HUECOS LIBRES PARA ${servicioDetectado.nombre} (${duracion} min, pueden empezar cada ${paso} min) ===`
      : `=== HUECOS LIBRES (cita estandar de ${duracion} min, pueden empezar cada ${paso} min) ===`,
    libres.length
      ? libres.map((d) => `${d.dia} ${d.fecha}: ${rangos(d.horas)}`).join('\n')
      : 'No queda ningun hueco libre en los proximos 7 dias.',
    'Reglas de disponibilidad:',
    `- Los rangos son horas de INICIO posibles: dentro de "09:00-11:00" vale cualquier hora en saltos de ${paso} minutos.`,
    '- Si el usuario PREGUNTA que huecos hay, respondele usando esos rangos, sin inventarte ninguno.',
    '- Si el usuario PIDE una hora concreta, NO juzgues si esta libre: limitate a rellenar date y time. De comprobarlo se encarga el sistema.',
  ].join('\n'));
}

// === Cartera de inmuebles ===
// Solo para clientes con el modulo `inmuebles` (migracion 0025). La IA no ve
// las fichas: ve lo que EXISTE --tipos, municipios, zonas y extras-- para
// traducir lo que pide la persona a esos nombres («San José» -> Sant Josep), y
// rellena el campo `inmuebles` del JSON. Busca `buscar_inmuebles` y la lista la
// escribe `Respuesta con inmuebles`: asi el modelo no puede ofrecer un piso que
// no existe ni cambiarle el precio a uno que si.
const cartera = [];

if (busqueda.tiene_inmuebles) {
  const c = $('Cartera de inmuebles').first().json || {};

  if (Number(c.total) > 0) {
    const NO_VIVIENDA = ['local', 'nave', 'oficina', 'parcela', 'garaje', 'terreno', 'solar'];
    const miles = (n) => String(Math.round(Number(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const p = c.precios || {};
    const resumen = [];
    if (p.venta) resumen.push(`${p.venta.cuantos} en venta (de ${miles(p.venta.desde)} a ${miles(p.venta.hasta)} €)`);
    if (p.alquiler) resumen.push(`${p.alquiler.cuantos} en alquiler (de ${miles(p.alquiler.desde)} a ${miles(p.alquiler.hasta)} €/mes)`);

    cartera.push([
      '=== CARTERA DE INMUEBLES (lo unico que existe) ===',
      `Disponibles ahora: ${resumen.join(' y ')}.`,
      // Agrupados: con la lista plana, «busco una vivienda» se tradujo como
      // los tipos de casa y sin pisos (06/10/2026), y en Sant Josep, que solo
      // tiene pisos, no salia nada.
      'Tipos de vivienda: ' + (c.tipos || []).filter((t) => !NO_VIVIENDA.includes(t)).join(', '),
      'Tipos para negocio o suelo: ' + (c.tipos || []).filter((t) => NO_VIVIENDA.includes(t)).join(', '),
      'Municipios y sus zonas:',
      (c.municipios || []).map((m) => `- ${m.municipio}: ${(m.zonas || []).join(', ')}`).join('\n'),
      'Extras: ' + (c.extras || []).join(', '),
      '',
      'TU NO VES LAS FICHAS: las busca el sistema. Para buscar, anade al JSON el campo "inmuebles":',
      '{"operacion": "venta" o "alquiler" o null, "tipos": [], "municipios": [], "zonas": [], "precio_min": numero o null, "precio_max": numero o null, "habitaciones_min": numero o null, "banos_min": numero o null, "m2_min": numero o null, "extras": [], "refs": []}',
      'Reglas de la busqueda:',
      '- Antes de buscar necesitas saber si es para COMPRAR o ALQUILAR y QUE busca (vivienda, local, nave...). Si no lo sabes, preguntalo y deja "inmuebles" en null.',
      '- Cuando lo sepas, rellena "inmuebles" en cada mensaje en que pida ver opciones o cambie algun criterio. Pon TODOS los criterios que haya dicho en la conversacion, no solo los de este mensaje; si cambia uno ("mejor hasta 200.000"), cambia ese y deja los demas.',
      '- Usa SOLO los nombres de tipos, municipios, zonas y extras de esta lista, escritos igual. Traduce lo que diga la persona: "San Jose" -> "Sant Josep"; "con parking" -> "garaje".',
      '- "Una vivienda", "una casa", "algo para vivir" sin mas = TODOS los tipos de vivienda de la lista, pisos y aticos incluidos. Con eso ya sabes QUE busca: busca, no preguntes que tipo.',
      '- Un municipio va en "municipios"; "zonas" es solo para barrios o zonas dentro de un municipio.',
      '- Precios en euros y como numero: "150 mil" -> 150000. En alquiler, la renta al mes. "Hasta 150.000" o "unos 150.000" es precio_max.',
      '- "refs": solo si pregunta por una referencia concreta ("el 104", "ref 207"); entonces deja vacio todo lo demas.',
      '- Si pregunta algo de un inmueble que YA le has ensenado y la respuesta esta en la conversacion, contesta tu y deja "inmuebles" en null. Si no esta, busca por su referencia.',
      '- Cuando rellenes "inmuebles", reply va VACIO (""), salvo que tengas que contestar otra cosa que haya preguntado. NUNCA escribas tu inmuebles, precios ni referencias: la lista la pone el sistema detras de tu reply.',
      '- NUNCA digas que no hay algo sin haberlo buscado: busca, y el sistema dira lo que haya.',
      '- Si pide MAS opciones ("no tienes nada mas?", "otras?"), vuelve a buscar con los mismos criterios: el sistema ya no repite lo que le ha ensenado.',
      '- Si el sistema le ha ofrecido mirar en otras zonas y dice que si, busca otra vez SIN "zonas" (deja el municipio y lo demas).',
      '- En cualquier otro caso, "inmuebles": null.',
    ].join('\n'));
  }
}

// === Instrucciones ===
// Dos juegos según el cliente reserve citas o solo atienda. El formato JSON de
// salida es el mismo en los dos casos para no tener que tocar los nodos que
// vienen después.
const instruccionesAgenda = [
  'Tu tarea es EXTRAER datos y conversar. La disponibilidad la decide el sistema, nunca tu.',
  '',
  'Responde SIEMPRE en JSON con esta forma exacta:',
  '{"reply": "tu respuesta al usuario", "date": "YYYY-MM-DD" o null, "time": "HH:mm" o null, "servicio": "lo que se va a hacer" o null, "trabajador": "la persona que pide" o null, "confirmar": true o false, "cambiar_cita": true o false, "anular_cita": true o false, "email": "el email del usuario" o null, "motivo": "el servicio que pide" o null, "escalar": true o false}',
  '',
  'Para dar una cita hacen falta TRES cosas: QUE se va a hacer, que DIA y a que HORA.',
  '- servicio: ponlo con el nombre EXACTO de la lista de servicios reservables. Si lo dice con otras palabras ("mechitas", "cortarme el pelo"), traducelo al de la lista. Si no encaja en ninguno, dejalo en null.',
  '- trabajador: solo si pide a alguien por su nombre. Si le da igual quien le atienda, null.',
  '- confirmar: true cuando esta pidiendo la cita ("dame cita", "reservamela", "el viernes a las 5 me va bien"). false cuando solo pregunta ("tienes hueco el viernes?"). Ante la duda, false: es peor crearle una cita que no ha pedido que preguntarle una vez mas.',
  '- Una negativa NUNCA es una confirmacion. Si el ultimo mensaje es "no", "no hace falta", "dejalo", "mejor no" o parecido, confirmar va en false y en reply no des ninguna cita por hecha: di que no reservas nada y ofrece ayudar en otra cosa.',
  '- cambiar_cita: true SOLO cuando quiere mover a otro dia u hora una cita que YA tiene ("no me va bien el martes, mejor el miercoles", "me la puedes cambiar a las 6?"). Entonces date y time son los NUEVOS, y NO crees otra cita. Si pide algo de su cita que no sea cambiarla de hora ni anularla, cambiar_cita en false y escalar en true.',
  '- anular_cita: true cuando quiere ANULAR una cita que ya tiene ("no voy a poder ir, anulala", "quiero cancelar mi cita"). Tambien cuando le has preguntado si de verdad quiere anularla y dice que si. confirmar va en true SOLO en ese segundo caso, cuando ya ha confirmado; mientras tanto, false.',
  '- Con cambiar_cita, confirmar significa lo mismo que siempre: false mientras solo pregunta si hay hueco, true cuando ya ha dicho que si a una hora concreta.',
  '- El email NO hace falta para reservar. Pidelo unicamente si tu prompt te lo pide.',
  '- Todos estos datos son los que haya dicho en CUALQUIER momento de la conversacion. Pon null solo si de verdad no lo ha dicho nunca.',
  '- Rellena SIEMPRE date y time si ha mencionado un dia y una hora, AUNQUE creas que esa hora podria estar ocupada.',
  '- NUNCA digas que una hora no esta disponible, y NUNCA ofrezcas alternativas por tu cuenta: de eso se encarga el sistema despues de ti.',
  '- En reply: si falta algo, pide UNICAMENTE lo que falte. Si ya lo tienes todo, escribe una confirmacion breve.',
  '- No vuelvas a preguntar un dato que el usuario ya te dio antes.',
].join('\n');

const instruccionesTienda = [
  'Atiendes a clientes de este negocio por WhatsApp. Tu trabajo es resolver dudas y',
  'asesorar sobre los productos con informacion veraz.',
  '',
  'Responde SIEMPRE en JSON con esta forma exacta:',
  '{"reply": "tu respuesta al usuario", "date": null, "time": null, "email": null, "motivo": null, "escalar": true o false, "presupuesto": null}',
  '',
  // Opcional por cliente: solo lo usa quien lo pide en su prompt (Cestería, para
  // que las peticiones de precio lleguen a su buzón de presupuestos). Al resto
  // les queda siempre en null y no cambia nada.
  '- presupuesto: dejalo SIEMPRE en null, salvo que tu prompt te pida recoger los datos de un presupuesto.',
  '  En ese caso, en el mensaje en que ya tienes los datos y se lo pasas al equipo, rellenalo asi:',
  '  {"nombre": "...", "tipo_cliente": "particular" o "profesional", "producto": "...", "medidas_unidades": "...", "email": "...", "direccion": "direccion de envio con codigo postal"}',
  '  Copia cada dato tal cual te lo dio; si alguno no lo tienes, ponlo en null. Antes de tener al menos el producto y el email, null.',
  '',
  '- Escribe como en un chat: breve, natural y directo. Nada de parrafadas ni de listas largas.',
  '- Este negocio NO gestiona citas por aqui: no propongas ninguna ni pidas fecha, hora o email para reservar.',
  '- Puedes recomendar y comparar productos, pero solo con los datos que tengas delante.',
  '- Si te preguntan algo que no puedes resolver (un pedido concreto, una incidencia,',
  '  un presupuesto a medida), dilo claramente y pasa el telefono o el correo del negocio.',
  '- Ante la duda, es mejor decir "eso te lo confirman mejor por telefono" que arriesgar un dato.',
].join('\n');

const messages = [{ role: 'system', content: cfg.system_prompt || '' }];

// Se mantiene por compatibilidad con los clientes que todavia usan el campo de
// texto libre. Cuando su contenido este pasado a documentos, este bloque sobra.
if (cfg.knowledge_base) {
  messages.push({
    role: 'system',
    content: 'Base de conocimiento del negocio:\n' + cfg.knowledge_base,
  });
}

messages.push({
  role: 'system',
  content: busqueda.tiene_agenda ? instruccionesAgenda : instruccionesTienda,
});

// === Cuándo avisar a una persona ===
// El bot no deja de responder por su cuenta: contesta lo que diga su prompt y,
// además, levanta la mano. Quien decide tomar el mando es la persona que mira
// la bandeja, no el modelo.
messages.push({
  role: 'system',
  content: [
    'Marca escalar: true cuando el usuario pida hablar con una persona, este enfadado o',
    'insatisfecho, reclame algo, pregunte por un pedido o una incidencia concreta, o haga',
    'una pregunta que no puedes responder con la informacion que tienes.',
    'En el resto de casos, escalar: false. No lo menciones nunca en tu respuesta.',
    'El campo escalar es OBLIGATORIO: tiene que aparecer siempre en el JSON, con true o con false.',
  ].join('\n'),
});

messages.push(...previos);

// El conocimiento y el calendario van DESPUES del historial, pegados al mensaje
// actual. Si quedan enterrados al principio, el modelo se guia por lo que el
// mismo dijo en mensajes anteriores en vez de por los datos buenos.
if (conocimiento.length) {
  messages.push({ role: 'system', content: conocimiento.join('\n\n') });
}
if (calendario.length) {
  messages.push({ role: 'system', content: calendario.join('\n') });
}
if (cartera.length) {
  messages.push({ role: 'system', content: cartera.join('\n') });
}

// === Adjuntos ===
// Si lo que llego no era texto escrito, el modelo tiene que saberlo. Sin esto
// trataria la transcripcion de un audio como si la persona la hubiera tecleado,
// y ante una foto que no se ha podido abrir se inventaria que la ha visto.
const adjunto = $('Extraer mensaje').first().json.adjunto;

if (adjunto) {
  messages.push({
    role: 'system',
    content: adjunto.leido
      ? 'El ultimo mensaje no es texto escrito: la persona ha enviado ' + adjunto.etiqueta +
        ' y lo que sigue es lo que se ha podido leer de ahi. Respondele con naturalidad, sin ' +
        'mencionar que lo has transcrito ni descrito.'
      : 'La persona ha enviado ' + adjunto.etiqueta + '. No puedes acceder a su contenido: ' +
        'dilo con naturalidad y pidele que te lo cuente por escrito. No te inventes que hay dentro.',
  });
}

// La presentacion va en un campo aparte y no dentro de reply, porque reply no
// siempre llega a enviarse: cuando se pide hora, lo que sale es el texto de la
// agenda. Respuesta final la pone delante de lo que se vaya a mandar.
if (presentarse) {
  messages.push({
    role: 'system',
    content: [
      'Es la primera vez que hablas con esta persona, o hace tiempo que no le escribes tu.',
      'Anade al JSON el campo "presentacion": UNA frase corta que diga que eres el asistente virtual',
      'del negocio, con el nombre que usa tu prompt. Por ejemplo: "Hola, soy el asistente virtual de <negocio>."',
      'Tiene que quedar claro que eres un asistente automatico y no una persona.',
      'Escribela en el mismo idioma en que te escribe la persona.',
      // Antes decía «reply empieza directamente por la respuesta», sin más, y el
      // modelo lo leía como «nada de cortesías»: Cestería pide en su prompt
      // agradecer el primer mensaje y preguntar el nombre, y con un «hola» a
      // secas el bot contestaba «¿En qué puedo ayudarte?» y nada más. Lo que
      // sobra es repetir el saludo y la presentación, no lo demás.
      'NO repitas el saludo ("hola", "buenas") ni la presentacion dentro de reply. Pero lo que pida tu prompt para el primer mensaje (agradecer que escriba, preguntar su nombre, dar la bienvenida) SI va en reply, al principio.',
    ].join('\n'),
  });
}

messages.push({ role: 'user', content: $('Extraer mensaje').first().json.message_text });

return [{ json: { messages, presentarse } }];

const ia = $input.first().json;

// Un cliente sin modulo de agenda no reserva nada: aunque la IA devolviera
// una fecha, no hay calendario contra el que comprobarla.
const tieneAgenda = $('Preparar búsqueda').first().json.tiene_agenda;

const aMin = (h) => { const [a, b] = h.split(':').map(Number); return a * 60 + b; };
const dosCifras = (n) => String(n).padStart(2, '0');
const aTexto = (m) => dosCifras(Math.floor(m / 60)) + ':' + dosCifras(m % 60);

// La hora que el usuario escribe manda sobre la que extrae la IA: se la ha visto
// devolver time=null con la hora delante, y coger la primera opcion de su propia
// lista de alternativas (le pides 12:30 y reserva 12:15).
function horaDelTexto(txt) {
  const t = String(txt || '').toLowerCase();
  // Se evita el punto como separador suelto: '4.08' es una fecha, no las 04:08.
  const patrones = [
    /\blas\s+(\d{1,2})(?:\s*[:.,'’h]\s*(\d{2}))?/,
    /\b(\d{1,2})\s*[:'’]\s*(\d{2})\b/,
    /\b(\d{1,2})\s*[.,]\s*(\d{2})\s*h\b/,
    /\b(\d{1,2})\s*h\s*(\d{2})\b/,
    /\b(\d{1,2})\s*h\b/,
  ];
  for (const p of patrones) {
    const m = t.match(p);
    if (!m) continue;
    const h = Number(m[1]);
    const min = m[2] === undefined ? 0 : Number(m[2]);
    if (h < 24 && min < 60) return dosCifras(h) + ':' + dosCifras(min);
  }
  return null;
}

// La hora que el usuario escribe manda sobre la que extrae la IA.
const hora = horaDelTexto($('Extraer mensaje').first().json.message_text) || ia.time || null;
const fecha = ia.date || null;
const email = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(String(ia.email || '').trim())
  ? String(ia.email).trim()
  : '';

// Que se hace y con quien. Los dos viajan como texto libre: el emparejamiento
// contra el catalogo real lo hace el motor, no el modelo. Si la IA devuelve
// "mechitas" y el servicio se llama "Mechas medio casco", el motor lo resuelve;
// y si se inventa uno que no existe, el motor lo dice en vez de reservar una
// duracion equivocada.
const servicio = String(ia.servicio || '').trim();
const trabajador = String(ia.trabajador || '').trim();

// Reservar en cuanto hay dia y hora convertiria cada "¿tienes hueco el viernes
// a las 5?" en una cita que nadie ha pedido. Asi que la reserva necesita ademas
// que la persona la este pidiendo; ante la duda se comprueba y se le pregunta.
//
// Y un "no" es un no. A "¿te la reservo?" se le contesto "No hace falta" y la IA
// lo leyo como "no hace falta que preguntes": confirmar=true y cita creada. El
// prompt ya pedia lo contrario, pero un prompt es una recomendacion y esto crea
// citas reales, asi que la ultima palabra la tiene el codigo.
const normalizar = (t) => String(t || '')
  .normalize('NFD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9ñ ]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Solo si el mensaje ENTERO es la negativa: "no me va bien el lunes, reservame
// el martes" tambien empieza por no, y esa si es una reserva.
const NEGATIVA = /^(no|no no|nop|que no|nada|ya no|ahora no|mejor no|no hace falta|no hace falta gracias|no me hace falta|no gracias|gracias no|dejalo|dejalo estar|dejemoslo|lo dejamos|mejor lo dejamos|olvidalo|otro dia|de momento no|no de momento|por ahora no|no por ahora|todavia no|aun no|no quiero|no quiero cita)$/;
const dijoQueNo = NEGATIVA.test(normalizar($('Extraer mensaje').first().json.message_text));

const confirmar = ia.confirmar === true && !dijoQueNo;

// El email ya no entra en esta decision. Dejo de ser un requisito cuando la
// confirmacion pasa a leerse en el propio chat; si lo dan, viaja igual.
// Con un no por delante no se reserva y tampoco se comprueba: volver a decir
// "esta libre, ¿te la reservo?" despues de un no es no haber escuchado.
// Cambiar una cita no es reservar otra: la agenda busca la que ya tiene y la
// mueve. Aqui no hacen falta fecha ni hora para arrancar --si no las ha dicho,
// el motor pregunta a cuando--, porque el "que" se decidio el dia que la pidio.
const cambiarCita = ia.cambiar_cita === true;

// Anular es lo mismo con otro final. Si la IA marca las dos cosas, gana mover:
// "anula la del martes y dame el jueves" es un cambio, y moverla conserva lo
// que ya tenia apuntado.
const anularCita = ia.anular_cita === true;

// Anular SIEMPRE pasa por la pregunta. Es lo unico que no se deshace por el
// chat, y "no voy a poder ir" a veces quiere decir "cambiamela". El prompt ya
// lo pedia, y aun asi la IA marco confirmar=true a la primera (29/09/2026): la
// cita se anulo sin preguntar. Asi que el si solo cuenta si lo ultimo que dijo
// el bot fue justo esa pregunta.
let ultimaDelBot = '';
try {
  const previo = $('Cargar historial').all()
    .map((i) => i.json)
    .find((m) => m && m.role === 'assistant' && m.content);
  ultimaDelBot = previo ? String(previo.content) : '';
} catch (e) {
  ultimaDelBot = '';
}
const yaPreguntoSiAnular = /seguro que quieres anular/i.test(ultimaDelBot);

let accion = 'ninguna';
if (!dijoQueNo && tieneAgenda) {
  if (cambiarCita) accion = 'mover';
  else if (anularCita) accion = 'anular';
  else if (fecha && hora) accion = confirmar ? 'reservar' : 'comprobar';
}

// Si la IA ya habia escrito la confirmacion en su respuesta, esa frase no puede
// salir: diria "queda confirmada" sin cita detras. Mejor una linea neutra.
let reply = ia.reply;
if (dijoQueNo && /(confirmad|reservad|te la reservo|apuntad|listo)/.test(normalizar(reply))) {
  reply = 'Vale, no reservo nada entonces. Si lo quieres mirar en otro momento, dímelo por aquí 👍';
}

const confirmarDeVerdad = accion === 'anular' ? confirmar && yaPreguntoSiAnular : confirmar;

// === Busqueda de inmuebles ===
// La IA solo extrae los criterios, y aqui se limpian antes de mandarlos a
// `buscar_inmuebles`: vienen de un modelo, y una lista puede llegar como cadena,
// un precio como "150.000", "150 mil" o 150, y la operacion como "compra".
// Si en el mismo mensaje hay algo de agenda (pide visita), manda la agenda.
const tieneInmuebles = $('Preparar búsqueda').first().json.tiene_inmuebles === true;

function lista(v) {
  const arr = Array.isArray(v) ? v : (v === null || v === undefined || v === '' ? [] : [v]);
  return arr.map((x) => String(x).trim()).filter(Boolean).slice(0, 10);
}

function numero(v) {
  if (typeof v === 'number') return isFinite(v) && v > 0 ? v : null;
  const t = String(v === null || v === undefined ? '' : v).trim().toLowerCase();
  if (!t) return null;
  const mil = t.match(/^(\d+(?:[.,]\d+)?)\s*(k|mil)$/);
  if (mil) return Number(mil[1].replace(',', '.')) * 1000;
  const n = Number(t.replace(/[.\s€]/g, '').replace(',', '.'));
  return isFinite(n) && n > 0 ? n : null;
}

function filtrosInmuebles(f) {
  if (!f || typeof f !== 'object' || Array.isArray(f)) return null;

  const op = normalizar(f.operacion);
  const operacion = /^(venta|compra|comprar)$/.test(op) ? 'venta'
    : /^(alquiler|alquilar)$/.test(op) ? 'alquiler'
    : null;

  const filtros = {
    operacion,
    tipos: lista(f.tipos),
    municipios: lista(f.municipios),
    zonas: lista(f.zonas),
    extras: lista(f.extras),
    refs: lista(f.refs),
    precio_min: numero(f.precio_min),
    precio_max: numero(f.precio_max),
    habitaciones_min: numero(f.habitaciones_min),
    banos_min: numero(f.banos_min),
    m2_min: numero(f.m2_min),
  };

  // "Hasta 150" en una compra son 150.000: asi lo dice todo el mundo. Y un
  // alquiler de 150.000 al mes es un dato cambiado de sitio: con el se buscaria
  // y no saldria nada, asi que mejor sin tope.
  for (const k of ['precio_min', 'precio_max']) {
    if (filtros[k] === null) continue;
    if (operacion === 'venta' && filtros[k] < 1000) filtros[k] = filtros[k] * 1000;
    if (operacion === 'alquiler' && filtros[k] > 20000) filtros[k] = null;
  }

  return filtros;
}

const inmuebles = tieneInmuebles && accion === 'ninguna' && !dijoQueNo
  ? filtrosInmuebles(ia.inmuebles)
  : null;

// Lo ya enseñado en esta conversacion no se vuelve a enseñar: la base lo
// excluye y lo cuenta aparte («aparte de los que ya te he enseñado...»). En la
// primera prueba real (06/10/2026), «¿no tienes nada mas?» devolvia las mismas
// tres fichas una y otra vez. Las referencias salen de las fichas que escribio
// el propio bot, que siempre empiezan por «*Ref. 104*». Al preguntar por una
// referencia concreta no se excluye nada: si pide el 104, quiere el 104.
if (inmuebles && !inmuebles.refs.length) {
  let ensenadas = [];
  try {
    for (const m of $('Cargar historial').all().map((i) => i.json)) {
      if (!m || m.role !== 'assistant' || !m.content) continue;
      for (const r of String(m.content).matchAll(/\*Ref\. ([A-Za-z0-9-]+)\*/g)) ensenadas.push(r[1]);
    }
  } catch (e) {
    ensenadas = [];
  }
  inmuebles.excluir_refs = [...new Set(ensenadas)];
}

// «En otras zonas de Ontinyent tengo 3 mas. ¿Te los enseño?» -> «si». Aceptar
// es buscar sin la zona. Se le pedia a la IA que la quitara, y en la prueba
// (06/10/2026) la dejo puesta tres mensajes seguidos: el bot repetia la misma
// oferta en bucle. Lo decide el codigo, igual que el «no» de las citas. Cuenta
// como aceptar tanto el «si» como pedir mas («¿no tienes nada mas?»).
if (inmuebles && !inmuebles.refs.length && inmuebles.zonas.length) {
  const ofrecioOtrasZonas = /En otras zonas\b[^\n]*¿Te los? enseño\?/.test(ultimaDelBot);
  const texto = normalizar($('Extraer mensaje').first().json.message_text);
  const acepta = /^(si|vale|venga|claro|ok|okey|okay|dale|perfecto|bueno|de acuerdo|adelante|a ver|porfa|por favor|ensena\w*|muestra\w*|pasa\w*|manda\w*)\b/.test(texto);
  const pideMas = /\b(nada mas|algo mas|alguno mas|alguna mas|mas opciones|otras opciones|otros|otras)\b/.test(texto);
  if (ofrecioOtrasZonas && (acepta || pideMas)) inmuebles.zonas = [];
}

return [{ json: { fecha, hora, email, servicio, trabajador, accion, confirmar: confirmarDeVerdad, motivo: ia.motivo || '', reply, escalar: ia.escalar === true, inmuebles } }];

const api = $input.first().json || {};

let reply = api.mensaje;

if (!reply) {
  reply = 'Ahora mismo no puedo consultar la agenda. Inténtalo de nuevo en un momento.';
} else if (api.mover && api.libre && !api.movida) {
  // Es un cambio, no una cita nueva: preguntarlo mal aqui es lo que hace que
  // alguien conteste "si" creyendo que le quedan dos.
  reply = reply + ' ¿Te la cambio?';
} else if (api.libre && !api.reservada) {
  // El hueco esta libre y la persona todavia no ha pedido la cita: solo estaba
  // preguntando. Antes aqui se le pedia el email, que era el requisito que
  // faltaba para reservar; ahora lo unico que falta es que diga que si.
  reply = reply + ' ¿Te la reservo?';
}

// `escalar` puede venir de dos sitios: de la IA (la persona ha pedido que
// le atienda alguien) o de la propia agenda (ya tenia cita y hay que
// cambiarsela). Las dos acaban en el mismo aviso al equipo.
// `aviso` es lo que tiene que saber el negocio aunque nadie haya pedido
// hablar con una persona: una cita cambiada o anulada. Va por el mismo canal
// que los avisos de siempre, pero sin marcar la conversacion.
return [{ json: { reply, escalar: api.escalar === true, aviso: api.aviso || null } }];

// Punto de encuentro de las dos ramas, para que los nodos siguientes tengan
// un único sitio del que leer el texto que se envía.
//
// Aquí se pone también la presentación del asistente, cuando toca (lo decide
// Preparar contexto). Se hace en código y no confiando en la IA: la frase la
// redacta ella, porque sabe cómo se llama el negocio, pero que salga lo
// garantiza esto. Si no la ha escrito, o no deja claro que es un asistente,
// va una genérica.
const presentarse = $('Preparar contexto').first().json.presentarse === true;
if (!presentarse) return $input.all();

const DICE_QUE_ES_ASISTENTE =
  /(asistente|assistent)\b[^.!?\n]{0,25}(virtual|autom[aà]tic)|\b(bot|chatbot)\b|intel[·.]?ligencia artificial|inteligencia artificial/i;
// Para dar por buena la respuesta tal cual hace falta más: que se presente
// ella misma. Que salga la palabra «bot» no basta — el bot de Kivuk habla de
// bots en cada respuesta («el bot puede ayudarte…») sin haberse presentado.
const YA_SE_PRESENTA =
  /\b(soy|s[oó]c)\s+(el|la|un|una|l'|l’)?\s*(asistente|assistent|bot|chatbot)\b/i;
const GENERICA = 'Hola, te atiende un asistente virtual.';

const propia = String($('Parsear respuesta IA').first().json.presentacion || '').trim();
const presentacion = DICE_QUE_ES_ASISTENTE.test(propia) ? propia : GENERICA;

// El saludo del principio de la respuesta sobra: la presentación ya saluda, y
// «Hola, soy el asistente…» seguido de «Hola, gracias por escribir» canta.
// Dos formas, por este orden:
//   - una frase corta de saludo con su propio signo o en su propia línea
//     («¡Hola, María!», «Buenas tardes 😊») se quita entera;
//   - si no, solo la palabra del saludo y su coma: «Buenas, las mechas
//     cuestan…» queda en «Las mechas cuestan…».
// «Hola María, …» (sin coma detrás del saludo) no se toca: quitar solo el
// «Hola» dejaría el nombre colgando.
const SALUDOS = '(hola|buenas tardes|buenas noches|buenos d[ií]as|buenas|bon dia|bona vesprada|bona nit)';
const SALUDO_CORTO = new RegExp('^\\s*¡?\\s*' + SALUDOS + '\\b[^.!?\\n]{0,20}([.!?]+|\\n)\\s*', 'i');
const SALUDO_Y_COMA = new RegExp('^\\s*¡?\\s*' + SALUDOS + '\\s*[,!.]+\\s*', 'i');

return $input.all().map((item) => {
  const original = String(item.json.reply || '');
  // Si la IA ya se ha presentado dentro de la respuesta, no se duplica.
  if (YA_SE_PRESENTA.test(original.slice(0, 200))) return item;

  let resto = SALUDO_CORTO.test(original)
    ? original.replace(SALUDO_CORTO, '')
    : original.replace(SALUDO_Y_COMA, '');
  if (!resto.trim()) resto = original;
  resto = resto.charAt(0).toUpperCase() + resto.slice(1);

  return { json: { ...item.json, reply: presentacion + '\n\n' + resto } };
});

// Este nodo recibe un item por cada módulo activo del cliente y los reduce a
// uno solo: a partir de aquí el flujo vuelve a tratar un único mensaje.
const modulos = $input.all().map((i) => i.json.module).filter(Boolean);

// Un bot de tienda no debe hablar de citas. En vez de duplicar el workflow por
// cliente, se mira si tiene activo el módulo de agenda y se adapta el contexto.
// Así el mismo workflow sirve para una clínica que reserva y para una tienda
// que solo asesora.
const tiene_agenda = modulos.includes('calendar');

// Lo mismo con la cartera de una inmobiliaria: solo quien tiene el módulo
// recibe la cartera en el contexto y el campo `inmuebles` en el JSON.
const tiene_inmuebles = modulos.includes('inmuebles');

const pregunta = String($('Extraer mensaje').first().json.message_text || '');

// Palabras demasiado comunes para buscar un producto con ellas: "cuanto",
// "precio" o "teneis" aparecen en media tienda y solo añaden ruido.
const VACIAS = new Set([
  'cuanto', 'cuanta', 'cuantos', 'cuantas', 'cuesta', 'cuestan', 'precio',
  'precios', 'vale', 'valen', 'tiene', 'tienen', 'teneis', 'hola', 'buenas',
  'gracias', 'quiero', 'queria', 'necesito', 'busco', 'buscaba', 'sobre',
  'para', 'como', 'donde', 'porque', 'puedo', 'puede', 'pueden', 'hacer',
  'decir', 'saber', 'favor', 'euros', 'envio', 'envios', 'pedido', 'tienda',
  'producto', 'productos', 'algun', 'alguna', 'tambien', 'mucho', 'mucha',
  'sois', 'estais', 'venden', 'vendeis', 'comprar', 'pagar', 'esta', 'este',
  'unas', 'unos', 'otra', 'otro', 'cual', 'cuales', 'vuestro', 'vuestra',
  // Verbos y comodines de uso. Se añadieron cuando la búsqueda empezó a mirar
  // también dentro de las descripciones: «algo para dejar la leña» dejaba los
  // términos en [algo, dejar, lena], y como se ordena por número de términos
  // cumplidos, un producto cuya descripción decía «algo» y «dejar» adelantaba a
  // un leñero que solo cumplía «leña». Con el nombre solo no molestaban porque
  // casi nunca aparecen ahí; en prosa están en todas partes.
  'algo', 'cosa', 'cosas', 'dejar', 'poner', 'tener', 'llevar', 'usar',
  'gustaria', 'quisiera', 'mirar', 'ideal', 'ideales', 'perfecto', 'perfecta',
]);

// El catálogo guarda los nombres en singular ("Cesto jacinto Valle") pero la
// gente pregunta en plural ("¿tenéis cestos?"). Sin esto, "cestos" no encuentra
// ni un producto y "cesto" encuentra tres. Como la comparación lleva comodines
// a los dos lados, acortar la palabra solo puede encontrar de más, nunca de
// menos; el mínimo de cuatro letras evita raíces tan cortas que valgan para
// cualquier cosa.
const singular = (p) => {
  const raiz = p.replace(/(es|s)$/, '');
  return raiz.length >= 4 ? raiz : p;
};

// Se comparan sin tildes porque por WhatsApp casi nadie las escribe, y la
// función buscar_productos aplica unaccent por el otro lado.
const terminos = [...new Set(
  pregunta
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    // Se descartan las palabras vacías dos veces, antes y después de recortar
    // el plural: si no, "teneis" pasaría el filtro convertido en "tenei" y se
    // buscaría en el catálogo un producto que contenga esa sílaba.
    .filter((p) => p.length >= 4 && !VACIAS.has(p))
    .map(singular)
    .filter((p) => !VACIAS.has(p))
)].slice(0, 5);

return [{
  json: {
    tiene_agenda,
    tiene_inmuebles,
    modulos,
    pregunta,
    terminos,
    // Sin términos útiles no tiene sentido mirar el catálogo: se piden cero
    // filas en lugar de lanzar una consulta que devolvería cualquier cosa.
    limite_productos: terminos.length ? 6 : 0,
  },
}];

// El nodo anterior devuelve una fila por item; aquí se recogen todas en un
// único item para que el resto del flujo siga tratando un solo mensaje.
//
// «Always Output Data» está activado en la búsqueda: cuando no hay resultados
// llega un item vacío en lugar de ninguno. Sin eso, un cliente sin conocimiento
// cargado cortaría el flujo aquí y el bot no contestaría nada.
const fragmentos = $input
  .all()
  .map((i) => i.json)
  .filter((f) => f && f.content);

return [{ json: { fragmentos } }];

parameters.jsonBody:
={
  "p_client_id": {{ JSON.stringify($('Buscar cliente Whatsapp').first().json.client_id) }},
  "p_terminos": {{ JSON.stringify($('Preparar búsqueda').first().json.terminos) }},
  "p_limite": {{ $('Preparar búsqueda').first().json.limite_productos }}
}

