parameters.jsCode:
const body = $json.body;
const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

// Sin mensaje no hay nada que hacer: por este mismo webhook llegan acuses de
// entrega y otros eventos que no son una conversacion.
if (!message) {
  return [];
}

// Una reaccion (un emoji sobre un mensaje) o un evento del sistema tampoco son
// una pregunta. Contestarlas seria ruido.
if (message.type === 'reaction' || message.type === 'system') {
  return [];
}

// Meta manda el nombre del perfil de WhatsApp junto al mensaje. Puede no venir
// (perfil sin nombre, o ajustes de privacidad), asi que es opcional. Se busca
// por wa_id en vez de coger el primero: en un webhook agrupado podria haber
// varios contactos y el primero no tiene por que ser el nuestro.
const contacto =
  value?.contacts?.find((c) => c.wa_id === message.from) || value?.contacts?.[0];
const nombre = contacto?.profile?.name?.trim() || null;

// Dos cosas distintas que antes se confundian:
//   se_guarda -> se descarga de Meta y se sube a Storage, para que una persona
//                pueda abrirlo desde la bandeja. Vale para todo.
//   se_lee    -> ademas se convierte a texto para que el bot lo entienda. Solo
//                audio (Whisper) e imagen (vision).
// Un video o un PDF no los entiende el bot, pero quien atiende si: por eso se
// guardan igual. Antes se descartaban en la primera linea del workflow y la
// persona se quedaba esperando una respuesta que no llegaba nunca.
const ADJUNTOS = {
  audio:    { etiqueta: 'una nota de voz', se_lee: true },
  image:    { etiqueta: 'una foto',        se_lee: true },
  video:    { etiqueta: 'un video',        se_lee: false },
  document: { etiqueta: 'un documento',    se_lee: false },
  sticker:  { etiqueta: 'un sticker',      se_lee: false },
  location: { etiqueta: 'una ubicacion',   se_lee: false },
  contacts: { etiqueta: 'un contacto',     se_lee: false },
};

const tipo = message.type;
const adjunto = ADJUNTOS[tipo] || null;
const media = message[tipo] || {};

// El tipo de archivo viene en el propio webhook, no hace falta preguntarselo a
// Meta. Importa: gracias a esto la ruta en Storage se puede calcular tanto
// aqui como al final, sin depender de nodos que quiza no se hayan ejecutado.
const mime = String(media.mime_type || '').split(';')[0].trim();
const ext = (mime.split('/')[1] || 'bin').replace(/[^a-z0-9]/gi, '');

return [{
  json: {
    phone_number_id: value.metadata.phone_number_id,
    from: message.from,
    contact_name: nombre,
    tipo,
    texto: tipo === 'text' ? (message.text?.body || '') : '',
    // El pie de foto o de video: lo que la persona escribio al enviarlo.
    pie: String(media.caption || '').trim(),
    media_id: media.id || null,
    mime: mime || null,
    ext,
    // Meta solo manda nombre de archivo en los documentos.
    nombre_archivo: media.filename || null,
    se_lee: Boolean(adjunto && adjunto.se_lee),
    etiqueta: adjunto
      ? adjunto.etiqueta
      : (tipo === 'text' ? null : 'un archivo'),
  }
}];

const bin = $input.first().binary?.data;

// Si la descarga fallo no hay binario. No se corta el flujo: se sigue sin
// descripcion y el bot dira que no ha podido abrir la foto.
if (!bin) {
  return [{ json: { data_uri: null } }];
}

// OJO: bin.data NO es el base64 cuando n8n guarda los binarios en disco
// (N8N_DEFAULT_BINARY_DATA_MODE=filesystem). En ese modo vale 'filesystem-v2',
// que es el identificador del fichero, y pegarlo en el data URI hace que OpenAI
// responda invalid_image_format. Hay que pedirle los bytes al helper.
// Con el modo 'memory' el helper devuelve lo mismo, asi que sirve para los dos.
let base64 = '';
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  base64 = buffer.toString('base64');
} catch (e) {
  // Respaldo por si el helper no estuviera disponible: solo se acepta si de
  // verdad parece base64 y no un identificador corto.
  base64 = typeof bin.data === 'string' && bin.data.length > 200 ? bin.data : '';
}

if (!base64) {
  return [{ json: { data_uri: null } }];
}

return [{
  json: {
    data_uri: 'data:' + (bin.mimeType || 'image/jpeg') + ';base64,' + base64,
  }
}];

