parameters.jsCode:
// Lo que ha recogido el bot, limpio, y el correo ya montado. El HTML se hace
// aquí y no en el nodo de Resend porque lleva texto escrito por el cliente, y
// hay que escaparlo: un «<» en una dirección no puede romper el correo.
const p = $('Parsear respuesta IA').first().json.presupuesto || {};
const limpio = (v) => (v === null || v === undefined ? '' : String(v)).replace(/\s+/g, ' ').trim();
const escapar = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const telefono = '+' + String($('Extraer mensaje').first().json.from).replace(/^\+/, '');
const datos = {
  nombre: limpio(p.nombre) || limpio($('Extraer mensaje').first().json.contact_name),
  tipo_cliente: limpio(p.tipo_cliente),
  producto: limpio(p.producto),
  medidas_unidades: limpio(p.medidas_unidades),
  email: limpio(p.email),
  direccion: limpio(p.direccion),
};
const fecha = $now.setZone('Europe/Madrid').toFormat('dd/MM/yyyy');

const filas = [
  ['Nombre del cliente', datos.nombre],
  ['Teléfono (WhatsApp)', telefono],
  ['Particular o profesional', datos.tipo_cliente],
  ['Producto', datos.producto],
  ['Medidas y unidades', datos.medidas_unidades],
  ['Email', datos.email],
  ['Dirección de envío y CP', datos.direccion],
  ['Fecha de la petición', fecha],
];
const html =
  '<p>Nueva solicitud de presupuesto recogida por el asistente de WhatsApp.</p>' +
  '<table style="border-collapse:collapse;font-family:sans-serif;font-size:14px">' +
  filas.map(([k, v]) =>
    '<tr><td style="padding:6px 12px;border:1px solid #ddd;background:#f6f6f6;font-weight:600">' + k +
    '</td><td style="padding:6px 12px;border:1px solid #ddd">' + (v ? escapar(v) : '<em style="color:#999">no lo ha dado</em>') + '</td></tr>'
  ).join('') +
  '</table>' +
  '<p>Puedes contestarle respondiendo a este correo, o seguir la conversación en el panel:</p>' +
  '<p><a href="https://panel.agenciakivuk.com/panel/conversaciones">Abrir la conversación</a></p>';

// El asunto lo fijó Cestería en su guía, para encontrarlos fácil en el buzón.
const asunto = 'WhatsApp – Presupuesto – ' + (datos.nombre || telefono);

return [{ json: {
  fila: {
    client_id: $('Buscar cliente Whatsapp').first().json.client_id,
    conversation_id: $('Buscar o crear conversación').first().json.id,
    telefono,
    ...Object.fromEntries(Object.entries(datos).map(([k, v]) => [k, v || null])),
  },
  asunto,
  html,
  // Responder al correo le escribe directamente al cliente final.
  responder_a: /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(datos.email) ? datos.email : null,
} }];

