parameters.jsCode:
// La lista de inmuebles la escribe el codigo, no la IA: con lo que devuelve
// `buscar_inmuebles`, tal cual. Un modelo que reescribe cifras alguna vez se
// equivoca de cifra, y aqui cada precio es una promesa a alguien que va a
// pedir una visita por el.
const decision = $('Decidir acción').first().json;
const filtros = decision.inmuebles || {};

// `buscar_inmuebles` devuelve un solo objeto (migracion 0026):
//   { filas: [...], total_exactos, vistos, otras_zonas }
// Si la llamada falla, `continueRegularOutput` deja pasar un item con `error`.
const r = $input.first().json || {};
const fallo = Boolean(r.error) || !Array.isArray(r.filas);
const filas = Array.isArray(r.filas) ? r.filas.filter((x) => x && x.ref) : [];

const miles = (n) => String(Math.round(Number(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const mayuscula = (t) => (t ? t.charAt(0).toUpperCase() + t.slice(1) : t);
const enumerar = (xs, y) => (xs.length <= 1 ? xs.join('') : xs.slice(0, -1).join(', ') + ' ' + (y || 'y') + ' ' + xs[xs.length - 1]);
const sinTildes = (t) => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
// "Ref. 104", "referencia 104" y "104" son la misma, igual que en la base.
const limpiaRef = (r) => sinTildes(r).replace(/^(referencia|ref)\W*/, '').replace(/[^a-z0-9]/g, '');

function donde(f) {
  if (!f.zona) return 'en ' + f.municipio;
  if (/^centro$/i.test(f.zona)) return 'en el centro de ' + f.municipio;
  return 'en ' + f.zona + ' (' + f.municipio + ')';
}

function precio(f) {
  if (f.precio === null || f.precio === undefined) return 'Precio a consultar';
  return miles(f.precio) + (f.operacion === 'alquiler' ? ' €/mes' : ' €');
}

// El estado solo se dice cuando cambia la decision: «a reformar» y «obra
// nueva» si; «buen estado» lo es casi todo y no aporta nada.
const ESTADOS_QUE_SE_DICEN = ['a reformar', 'para actualizar', 'reformado', 'obra nueva'];

// Si no ha dicho si compra o alquila, o pregunta por referencias, cada ficha
// lo dice: un precio de 850 sin «al mes» al lado no se sabe que es.
const decirOperacion = !filtros.operacion || (filtros.refs || []).length > 0;

function ficha(f) {
  const datos = [precio(f)];
  if (f.habitaciones > 0) datos.push(f.habitaciones + ' hab.');
  if (f.banos > 0) datos.push(f.banos + (Number(f.banos) === 1 ? ' baño' : ' baños'));
  if (f.m2 > 0) datos.push(miles(f.m2) + ' m²');
  if (f.m2_parcela > 0) datos.push('parcela de ' + miles(f.m2_parcela) + ' m²');
  if (ESTADOS_QUE_SE_DICEN.includes(sinTildes(f.estado))) datos.push(f.estado);

  const titulo = mayuscula(f.tipo) + (decirOperacion ? ' en ' + f.operacion : '') + ' ' + donde(f);
  const lineas = ['*Ref. ' + f.ref + '* · ' + titulo, datos.join(' · ')];

  const extras = Array.isArray(f.extras) ? f.extras : [];
  if (extras.length) lineas.push(mayuscula(enumerar(extras)) + '.');
  if (f.descripcion) lineas.push(f.descripcion + (/[.!?]$/.test(f.descripcion) ? '' : '.'));
  if (f.url) lineas.push(f.url);

  // Lo que se ha aflojado se dice en la misma ficha. Esconderlo seria que
  // la persona lo descubriera en la visita.
  if (f.encaje === 'se_pasa' && filtros.precio_max) {
    lineas.push('_Se pasa ' + miles(f.precio - filtros.precio_max) + ' € de lo que me dijiste._');
  }
  return lineas.join('\n');
}

// Lo que haya escrito la IA va delante, frase a frase. Se le pide que deje
// reply vacio, pero un prompt no es una garantia, y en las pruebas con gpt-4o
// (06/10/2026) lo llenaba casi siempre de dos maneras que, encima de una lista
// que ya esta, quedan raras:
//   - anunciando la busqueda: «Estoy buscando opciones para ti de inmediato»;
//   - preguntando: «¿Tienes algun presupuesto?», cuando el cierre del sistema
//     ya pide lo que falta para afinar.
// Esas frases se quitan, igual que las que traen cifras o referencias (una
// ficha escrita por ella) o acaban en dos puntos (una entradilla). Lo demas se
// queda: «Gracias por escribirnos» o la respuesta a otra cosa que pregunto.
const PARECE_UNA_FICHA = /€|\d{1,3}(\.\d{3})+|\bref(erencia)?\.?\s*\d/i;
// En castellano y en valenciano («Ara mateix busque opcions per a tu»).
const ANUNCIA_LA_BUSQUEDA = /\b(busc\w*|busq\w*|mir(o|ando|amos)|revis\w*|echo un vistazo|un momento?|te (enseño|muestro|paso|pongo)|mostrar\w*|enseñar\w*|necesito saber|aqu[ií] (tienes|van)|estas son|opci(ones|ons))\b/i;
const entrada = String(decision.reply || '')
  .trim()
  .split(/(?<=[.!?])\s+/)
  .filter((f) => f && !PARECE_UNA_FICHA.test(f) && !ANUNCIA_LA_BUSQUEDA.test(f) && !/[?:]\s*$/.test(f))
  .join(' ')
  .slice(0, 300)
  .trim();

const partes = [];
let escalar = false;

if (fallo && !filas.length) {
  // Sin cartera no se improvisa: se avisa al equipo y se le dice la verdad.
  partes.push('Ahora mismo no puedo consultar la cartera. Le paso tu búsqueda a un comercial y te escribe en cuanto pueda.');
  escalar = true;
} else if ((filtros.refs || []).length) {
  // --- por referencia -----------------------------------------------------
  const disponibles = filas.filter((f) => f.situacion === 'disponible');
  const reservados = filas.filter((f) => f.situacion === 'reservado');
  const encontradas = new Set(filas.map((f) => limpiaRef(f.ref)));
  const noEstan = filtros.refs.filter((r) => !encontradas.has(limpiaRef(r)));

  for (const f of disponibles) partes.push(ficha(f));
  for (const f of reservados) {
    partes.push('El ' + f.ref + ' (' + f.tipo + ' ' + donde(f) + ') está reservado ahora mismo. Si la reserva se cae, te lo decimos; mientras, si me cuentas qué buscas, te enseño algo parecido.');
  }
  if (noEstan.length) {
    partes.push((noEstan.length === 1 ? 'No tengo ninguna referencia ' : 'No tengo las referencias ') + enumerar(noEstan) + ' en la cartera. ¿Puede que sea otra? Si me dices qué buscas, te enseño lo que hay.');
  }
  if (disponibles.length) {
    partes.push(disponibles.length === 1
      ? '¿Quieres verlo? Dime qué día te va bien y te busco hueco para la visita.'
      : '¿Quieres ver alguno? Dime cuál y qué día te va bien, y te busco hueco para la visita.');
  }
} else {
  // --- por criterios ------------------------------------------------------
  // Lo ya enseñado en la conversacion no vuelve (lo excluye la base) y se
  // cuenta en `vistos`. Otras zonas no rellenan la lista: se cuentan en
  // `otras_zonas` y se ofrecen, porque elegir zona es cosa de la persona. Asi
  // se arreglo la primera prueba real (06/10/2026), en la que «¿no tienes nada
  // mas?» devolvia las mismas tres fichas, una de ellas de una zona que nadie
  // habia pedido.
  const exactos = filas.filter((f) => f.encaje === 'exacto');
  const cerca = filas.filter((f) => f.encaje === 'se_pasa');
  const total = Number(r.total_exactos) || exactos.length;
  const vistos = Number(r.vistos) || 0;
  const otras = Number(r.otras_zonas) || 0;

  const zonas = filtros.zonas || [];
  const laZona = enumerar(zonas, 'ni');
  const elResto = (filtros.municipios || []).length === 1 ? 'otras zonas de ' + filtros.municipios[0] : 'otras zonas';
  const yaLosVio = vistos === 1 ? 'el que ya te he enseñado' : 'los que ya te he enseñado';
  // La zona pedida se ha quedado sin nada nuevo que enseñar, pero en otras hay.
  const ofrecerOtrasZonas = zonas.length > 0 && otras > 0 && total <= exactos.length;

  if (exactos.length) {
    if (vistos) {
      partes.push('Aparte de ' + yaLosVio + ', tengo ' + (total === 1 ? 'otro que encaja' : total + ' más que encajan') +
        (total > exactos.length ? '; te pongo los ' + exactos.length + ' que más se ajustan:' : ':'));
    } else {
      partes.push(total === 1
        ? 'Tengo uno que encaja con lo que buscas:'
        : 'Tengo ' + total + ' que encajan con lo que buscas' + (total > exactos.length ? '; te pongo los ' + exactos.length + ' que más se ajustan:' : ':'));
    }
    for (const f of exactos) partes.push(ficha(f));
    if (cerca.length) partes.push(cerca.length === 1 ? 'Y este se acerca, por si te encaja:' : 'Y estos se acercan, por si te encajan:');
  } else if (cerca.length) {
    partes.push(vistos
      ? 'Aparte de ' + yaLosVio + ', justo con todo lo que pides no tengo más, pero esto se acerca:'
      : 'Justo con todo lo que pides no tengo nada ahora mismo, pero esto se acerca bastante:');
  } else if (vistos) {
    partes.push(zonas.length
      ? 'En ' + laZona + ' no tengo más aparte de ' + yaLosVio + '.'
      : 'Con lo que buscas no tengo más aparte de ' + yaLosVio + '.');
  } else {
    partes.push(zonas.length
      ? 'En ' + laZona + ' no tengo ahora mismo nada que cumpla todo eso.'
      : 'Ahora mismo no tengo nada que cumpla todo eso.');
  }
  for (const f of cerca) partes.push(ficha(f));

  const enseno = exactos.length + cerca.length;

  if (ofrecerOtrasZonas) {
    // «¿Te los enseño?» y no la lista: si dice que si, la IA quita la zona y
    // la siguiente busqueda ya no repite lo enseñado.
    partes.push((enseno ? 'Es todo lo que tengo en ' + laZona + '. ' : '') +
      'En ' + elResto + ' tengo ' + (otras === 1 ? 'uno más' : otras + ' más') + ' con lo que buscas. ' +
      (otras === 1 ? '¿Te lo enseño?' : '¿Te los enseño?') +
      (enseno ? ' Y si alguno de estos te gusta, dime la referencia y te busco hueco para verlo.' : ''));
  } else if (!enseno) {
    partes.push('Si quieres, aflojamos algo (la zona, el precio o las habitaciones) y miro otra vez, o le paso tu búsqueda a un comercial para que te avise en cuanto entre algo así.');
  } else {
    // Afinar: con muchos resultados, se pide lo que falta para quedarse con
    // los buenos. Es lo que haria el comercial antes de enseñar nada.
    const NO_VIVIENDA = ['local', 'nave', 'oficina', 'parcela', 'garaje', 'terreno', 'solar'];
    const tipos = (filtros.tipos || []).map(sinTildes);
    const esVivienda = !tipos.length || tipos.some((t) => !NO_VIVIENDA.includes(t));
    const faltan = [];
    if (!filtros.operacion) faltan.push('si es para comprar o alquilar');
    if (!(filtros.municipios || []).length && !zonas.length) faltan.push('la zona');
    if (!filtros.precio_max) faltan.push('hasta cuánto quieres gastar');
    if (esVivienda && !filtros.habitaciones_min) faltan.push('cuántas habitaciones necesitas');
    if (!esVivienda && !filtros.m2_min) faltan.push('los metros que necesitas');

    if (total > exactos.length && faltan.length) {
      partes.push('Si me dices ' + enumerar(faltan.slice(0, 2)) + ', te lo afino más. Y si alguno te gusta, dime la referencia y te busco hueco para verlo.');
    } else {
      partes.push(enseno === 1
        ? '¿Te gustaría verlo? Dime qué día te va bien y te busco hueco para la visita con el comercial.'
        : '¿Te gustaría ver alguno? Dime la referencia y te busco hueco para la visita con el comercial.');
    }
  }
}

const reply = [entrada, ...partes].filter(Boolean).join('\n\n');

// Las referencias enseñadas viajan aparte por si un nodo de despues las
// necesita (p. ej. para apuntar en la visita de que inmueble se trata).
return [{ json: { reply, escalar, aviso: null, inmuebles_mostrados: filas.map((f) => f.ref) } }];
